import { fileURLToPath } from "node:url";
import { drizzle } from "drizzle-orm/postgres-js";
import { migrate } from "drizzle-orm/postgres-js/migrator";
import postgres from "postgres";
import { withoutClientOnlyParams } from "./client";

/** The committed SQL migrations (generated by `pnpm db:generate`, reviewed before use). */
export const MIGRATIONS_FOLDER = fileURLToPath(new URL("../migrations", import.meta.url));

/**
 * Applies pending migrations as the migration role. `pnpm db:migrate` uses
 * drizzle-kit; tests and the Compose `migrate` service use this, against the
 * same folder and bookkeeping table.
 */
export async function runMigrations(url: string): Promise<void> {
  const client = postgres(withoutClientOnlyParams(url), { max: 1, onnotice: () => {} });
  try {
    await migrate(drizzle(client), {
      migrationsFolder: MIGRATIONS_FOLDER,
      migrationsTable: "__drizzle_migrations",
      migrationsSchema: "drizzle",
    });
  } finally {
    await client.end({ timeout: 5 });
  }
}

/** Hosts that only exist on a developer machine or inside the local Compose network. */
const LOCAL_HOSTS = new Set(["localhost", "127.0.0.1", "::1", "[::1]", "postgres"]);

export function isLocalDatabaseUrl(url: string): boolean {
  try {
    return LOCAL_HOSTS.has(new URL(url).hostname);
  } catch {
    return false;
  }
}

/** Host and database name only, for logs (never credentials). */
export function describeDatabaseUrl(url: string): string {
  try {
    const parsed = new URL(url);
    return `${parsed.hostname}${parsed.port ? `:${parsed.port}` : ""}${parsed.pathname}`;
  } catch {
    return "(unparseable database URL)";
  }
}

export const LOCAL_DIRECT_DATABASE_URL = "postgres://foliomind:foliomind@localhost:5433/foliomind";

/** DIRECT_DATABASE_URL, or the local Compose database when it is unset. */
export function migrationDatabaseUrl(
  env: Record<string, string | undefined> = process.env,
): string {
  return env.DIRECT_DATABASE_URL || LOCAL_DIRECT_DATABASE_URL;
}
